import sys
from collections import deque, defaultdict

MOD = 10**9 + 7

def bfs(graph, start):
    queue = deque([start])
    visited = {start}
    distances = {start: 0}

    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                distances[neighbor] = distances[node] + 1
                queue.append(neighbor)

    return distances

def calculate_diameter(graph, nodes):
    if not nodes:
        return 0

    # Find any node in the subgraph
    start_node = next(iter(nodes))
    distances = bfs(graph, start_node)

    # Find the farthest node from start_node
    farthest_node = max(distances, key=distances.get)
    distances = bfs(graph, farthest_node)

    # The diameter is the maximum distance found
    return max(distances.values())

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    edges = [(int(data[2*i+1]), int(data[2*i+2])) for i in range(N-1)]

    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    total_sum = 0

    # Iterate over all possible subsets of nodes
    for mask in range(1, 1 << N):
        white_nodes = set()
        black_nodes = set()

        for i in range(N):
            if mask & (1 << i):
                white_nodes.add(i + 1)
            else:
                black_nodes.add(i + 1)

        X = calculate_diameter(graph, white_nodes)
        Y = calculate_diameter(graph, black_nodes)

        total_sum += max(X, Y)
        total_sum %= MOD

    print(total_sum)

